impl<'a, 'b> CreateTokenCpi<'a, 'b> {
	pub fn new(
		program: &'b solana_program::account_info::AccountInfo<'a>,
		accounts: CreateTokenCpiAccounts<'a, 'b>,
		args: CreateTokenInstructionArgs,
	) -> Self {
		Self {
			__program: program,
			user: accounts.user,
			payer: accounts.payer,
			coin_creator: accounts.coin_creator,
			global_config: accounts.global_config,
			base_mint: accounts.base_mint,
			quote_mint: accounts.quote_mint,
			bonding_curve: accounts.bonding_curve,
			base_vault: accounts.base_vault,
			quote_vault: accounts.quote_vault,
			creator_fee_config: accounts.creator_fee_config,
			nexus_program: accounts.nexus_program,
			nexus_global_config: accounts.nexus_global_config,
			partner: accounts.partner,
			partner_config: accounts.partner_config,
			nexus_staking_config: accounts.nexus_staking_config,
			staking_reward_state: accounts.staking_reward_state,
			reward_accrual: accounts.reward_accrual,
			staking_vault: accounts.staking_vault,
			staking_wsol_vault: accounts.staking_wsol_vault,
			wsol_reward_accrual: accounts.wsol_reward_accrual,
			pyth_price_feed: accounts.pyth_price_feed,
			base_token_program: accounts.base_token_program,
			quote_token_program: accounts.quote_token_program,
			wsol_token_program: accounts.wsol_token_program,
			associated_token_program: accounts.associated_token_program,
			system_program: accounts.system_program,
			event_authority: accounts.event_authority,
			program: accounts.program,
			__args: args,
		}
	}
	#[inline(always)]
	pub fn invoke(&self) -> solana_program::entrypoint::ProgramResult {
		self.invoke_signed_with_remaining_accounts(&[], &[])
	}
	#[inline(always)]
	pub fn invoke_with_remaining_accounts(
		&self,
		remaining_accounts: &[(
			&'b solana_program::account_info::AccountInfo<'a>,
			bool,
			bool,
		)],
	) -> solana_program::entrypoint::ProgramResult {
		self.invoke_signed_with_remaining_accounts(&[], remaining_accounts)
	}
	#[inline(always)]
	pub fn invoke_signed(
		&self,
		signers_seeds: &[&[&[u8]]],
	) -> solana_program::entrypoint::ProgramResult {
		self.invoke_signed_with_remaining_accounts(signers_seeds, &[])
	}
	#[allow(clippy::arithmetic_side_effects)]
	#[allow(clippy::clone_on_copy)]
	#[allow(clippy::vec_init_then_push)]
	pub fn invoke_signed_with_remaining_accounts(
		&self,
		signers_seeds: &[&[&[u8]]],
		remaining_accounts: &[(
			&'b solana_program::account_info::AccountInfo<'a>,
			bool,
			bool,
		)],
	) -> solana_program::entrypoint::ProgramResult {
		let mut accounts = Vec::with_capacity(28 + remaining_accounts.len());
		accounts
			.push(solana_instruction::AccountMeta::new(*self.user.key, true));
		accounts
			.push(solana_instruction::AccountMeta::new(*self.payer.key, true));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.coin_creator.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.global_config.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.base_mint.key,
			true,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.quote_mint.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.bonding_curve.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.base_vault.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.quote_vault.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.creator_fee_config.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.nexus_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.nexus_global_config.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.partner.0.key,
			self.partner.1,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.partner_config.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.nexus_staking_config.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.staking_reward_state.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.reward_accrual.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.staking_vault.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.staking_wsol_vault.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new(
			*self.wsol_reward_accrual.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.pyth_price_feed.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.base_token_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.quote_token_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.wsol_token_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.associated_token_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.system_program.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.event_authority.key,
			false,
		));
		accounts.push(solana_instruction::AccountMeta::new_readonly(
			*self.program.key,
			false,
		));
		remaining_accounts.iter().for_each(|remaining_account| {
			accounts.push(solana_instruction::AccountMeta {
				pubkey: *remaining_account.0.key,
				is_writable: remaining_account.1,
				is_signer: remaining_account.2,
			})
		});
		let mut data = CreateTokenInstructionData::new().try_to_vec().unwrap();
		let mut args = self.__args.try_to_vec().unwrap();
		data.append(&mut args);

		let instruction = solana_instruction::Instruction {
			program_id: crate::launchpad::generated::SEND_LAUNCHPAD_ID,
			accounts,
			data,
		};
		let mut account_infos =
			Vec::with_capacity(29 + remaining_accounts.len());
		account_infos.push(self.__program.clone());
		account_infos.push(self.user.clone());
		account_infos.push(self.payer.clone());
		account_infos.push(self.coin_creator.clone());
		account_infos.push(self.global_config.clone());
		account_infos.push(self.base_mint.clone());
		account_infos.push(self.quote_mint.clone());
		account_infos.push(self.bonding_curve.clone());
		account_infos.push(self.base_vault.clone());
		account_infos.push(self.quote_vault.clone());
		account_infos.push(self.creator_fee_config.clone());
		account_infos.push(self.nexus_program.clone());
		account_infos.push(self.nexus_global_config.clone());
		account_infos.push(self.partner.0.clone());
		account_infos.push(self.partner_config.clone());
		account_infos.push(self.nexus_staking_config.clone());
		account_infos.push(self.staking_reward_state.clone());
		account_infos.push(self.reward_accrual.clone());
		account_infos.push(self.staking_vault.clone());
		account_infos.push(self.staking_wsol_vault.clone());
		account_infos.push(self.wsol_reward_accrual.clone());
		account_infos.push(self.pyth_price_feed.clone());
		account_infos.push(self.base_token_program.clone());
		account_infos.push(self.quote_token_program.clone());
		account_infos.push(self.wsol_token_program.clone());
		account_infos.push(self.associated_token_program.clone());
		account_infos.push(self.system_program.clone());
		account_infos.push(self.event_authority.clone());
		account_infos.push(self.program.clone());
		remaining_accounts.iter().for_each(|remaining_account| {
			account_infos.push(remaining_account.0.clone())
		});

		if signers_seeds.is_empty() {
			solana_program::program::invoke(&instruction, &account_infos)
		} else {
			solana_program::program::invoke_signed(
				&instruction,
				&account_infos,
				signers_seeds,
			)
		}
	}
}

